def satisfiesConditions(grid):
    m = len(grid)
    n = len(grid[0])

    # Loop through each cell
    for i in range(m):
        for j in range(n):
            # Check cell below
            if i + 1 < m:
                if grid[i][j] != grid[i+1][j]:
                    return False

            # Check cell to the right
            if j + 1 < n:
                if grid[i][j] == grid[i][j+1]:
                    return False

    return True
